effect.shader:
void main() {
    // A correção de proporção é o que mantém a lente REDONDA num projeto 16:9.
    // Sem ela o efeito vira uma elipse achatada.
    vec2 p = (acScreenNorm - center) * vec2(acAspect, 1.0);
    float dist = length(p);

    if (dist >= radius || radius <= 0.0) {
        fragColor = texture(inputImg, acScreenNorm);
        return;
    }

    float ratio = dist / radius;

    // A curva `pow` faz a distorção ser forte no centro e ir a zero na borda do
    // raio. Um fator linear deixaria uma emenda visível no limite do círculo.
    float factor = pow(ratio, 1.0 + strength);

    vec2 warped = p * (factor / max(ratio, 0.0001));
    vec2 uv = center + warped / vec2(acAspect, 1.0);

    fragColor = texture(inputImg, clamp(uv, 0.0, 1.0));
}
